        assert!(json.contains(r#""estimatedTipHeight":335684"#));
        assert!(json.contains(r#""effectiveTargetHeight":null"#));
        assert!(json.contains(r#""lagBlocks":null"#));
        assert!(json.contains(r#""freshness":"unknown""#));
