    #[test]
    fn p2p_fallback_is_used_only_for_delegated_transport_failures() {
        let answer = ResolutionAnswer {
            name: DnsName::from_ascii("legacy.relaytest").unwrap(),
            records: vec![address_record("legacy.relaytest", [203, 0, 113, 44])],
            secure: true,
        };
        let relay = P2pFallbackDelegatedResolver::new(
            TestDelegatedResolver::error(|| {
                ResolverError::DnsTransport("authoritative UDP timed out".to_owned())
            }),
            TestDelegatedResolver::answer(answer.clone()),
            FallbackMarker::default(),
        );
        let request = ResolutionRequest {
            qname: "legacy.relaytest".to_owned(),
            qtype: RecordType::A.code(),
        };

        assert_eq!(
            relay
                .resolve_delegated(&request, &test_delegation("relaytest"))
                .unwrap(),
            answer,
        );

        let intercepted = P2pFallbackDelegatedResolver::new(
            TestDelegatedResolver::error(|| ResolverError::Port53InterceptionDetected),
            TestDelegatedResolver::answer(answer.clone()),
            FallbackMarker::default(),
        );
        assert_eq!(
            intercepted
                .resolve_delegated(&request, &test_delegation("relaytest"))
                .unwrap(),
            answer,
        );

        let terminal_errors: [(&str, ResolverErrorFactory); 5] = [
            ("response code", || ResolverError::DnsResponseCode(2)),
            ("malformed DNS", || ResolverError::InvalidDnsResponse),
            ("DNSSEC", || ResolverError::DnssecFailed),
            ("stale proof", || ResolverError::LocalChainNotCurrent),
            ("missing proof", || ResolverError::ProofUnavailable),
        ];
        for (label, terminal_error) in terminal_errors {
            let fallback_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let gated = P2pFallbackDelegatedResolver::new(
                TestDelegatedResolver::error(terminal_error),
                CountingAnswerDelegatedResolver {
                    calls: Arc::clone(&fallback_calls),
                    answer: answer.clone(),
                },
                FallbackMarker::default(),
            );
            assert_eq!(
                gated
                    .resolve_delegated(&request, &test_delegation("relaytest"))
                    .unwrap_err(),
                terminal_error(),
                "{label}",
            );
            assert_eq!(fallback_calls.load(Ordering::Relaxed), 0, "{label}");
        }
    }

    #[test]
    fn recovery_doh_is_only_used_for_transport_failure_or_confirmed_interception() {
        let answer = ResolutionAnswer {
            name: DnsName::from_ascii("site.recoverytest").unwrap(),
            records: vec![address_record("site.recoverytest", [203, 0, 113, 45])],
            secure: true,
        };
        let request = ResolutionRequest {
            qname: "site.recoverytest".to_owned(),
            qtype: RecordType::A.code(),
        };
        let delegation = test_delegation("recoverytest");

        for allowed in [
            ResolverError::DnsTransport("direct path timed out".to_owned()),
            ResolverError::Port53InterceptionDetected,
        ] {
            let fallback_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let resolver = RecoveryDohFallbackDelegatedResolver::new(
                TestDelegatedResolver {
                    outcome: TestResolverOutcome::Error(match allowed {
                        ResolverError::DnsTransport(_) => {
                            || ResolverError::DnsTransport("direct path timed out".to_owned())
                        }
                        ResolverError::Port53InterceptionDetected => {
                            || ResolverError::Port53InterceptionDetected
                        }
                        _ => unreachable!(),
                    }),
                },
                CountingAnswerDelegatedResolver {
                    calls: Arc::clone(&fallback_calls),
                    answer: answer.clone(),
                },
                FallbackMarker::default(),
            );
            assert_eq!(
                resolver.resolve_delegated(&request, &delegation).unwrap(),
                answer
            );
            assert_eq!(fallback_calls.load(Ordering::Relaxed), 1);
        }

        let terminal_errors: [(&str, ResolverErrorFactory); 5] = [
            ("response code", || ResolverError::DnsResponseCode(2)),
            ("malformed DNS", || ResolverError::InvalidDnsResponse),
            ("DNSSEC", || ResolverError::DnssecFailed),
            ("stale proof", || ResolverError::LocalChainNotCurrent),
            ("missing proof", || ResolverError::ProofUnavailable),
        ];
        for (label, terminal_error) in terminal_errors {
            let fallback_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
            let resolver = RecoveryDohFallbackDelegatedResolver::new(
                TestDelegatedResolver::error(terminal_error),
                CountingAnswerDelegatedResolver {
                    calls: Arc::clone(&fallback_calls),
                    answer: answer.clone(),
                },
                FallbackMarker::default(),
            );
            assert_eq!(
                resolver
                    .resolve_delegated(&request, &delegation)
                    .unwrap_err(),
                terminal_error(),
                "{label}",
            );
            assert_eq!(fallback_calls.load(Ordering::Relaxed), 0, "{label}");
        }
    }

    #[test]
    fn recovery_doh_remembers_the_failed_direct_path_per_hns_root() {
        let answer = ResolutionAnswer {
            name: DnsName::from_ascii("site.recoverytest").unwrap(),
            records: vec![address_record("site.recoverytest", [203, 0, 113, 46])],
            secure: true,
        };
        let primary_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let fallback_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let resolver = RecoveryDohFallbackDelegatedResolver::new(
            CountingErrorDelegatedResolver {
                calls: Arc::clone(&primary_calls),
                error: || ResolverError::DnsTransport("direct path blocked".to_owned()),
            },
            CountingAnswerDelegatedResolver {
                calls: Arc::clone(&fallback_calls),
                answer,
            },
            FallbackMarker::default(),
        );
        let delegation = test_delegation("recoverytest");

        for qtype in [RecordType::A, RecordType::Aaaa, RecordType::Tlsa] {
            resolver
                .resolve_delegated(
                    &ResolutionRequest {
                        qname: "site.recoverytest".to_owned(),
                        qtype: qtype.code(),
                    },
                    &delegation,
                )
                .unwrap();
        }

        assert_eq!(primary_calls.load(Ordering::Relaxed), 1);
        assert_eq!(fallback_calls.load(Ordering::Relaxed), 3);
    }

    #[test]
    fn recovery_doh_preserves_interception_but_not_bogus_dnssec() {
        let request = ResolutionRequest {
            qname: "site.recoverytest".to_owned(),
            qtype: RecordType::A.code(),
        };
        let delegation = test_delegation("recoverytest");
        for recovery_error in [
            ResolverError::DnsTransport("recovery unavailable".to_owned()),
            ResolverError::DnsResponseCode(2),
            ResolverError::InvalidDnsResponse,
        ] {
            let resolver = RecoveryDohFallbackDelegatedResolver::new(
                TestDelegatedResolver::error(|| ResolverError::Port53InterceptionDetected),
                TestDelegatedResolver {
                    outcome: TestResolverOutcome::Error(match recovery_error {
                        ResolverError::DnsTransport(_) => {
                            || ResolverError::DnsTransport("recovery unavailable".to_owned())
                        }
                        ResolverError::DnsResponseCode(_) => || ResolverError::DnsResponseCode(2),
                        ResolverError::InvalidDnsResponse => || ResolverError::InvalidDnsResponse,
                        _ => unreachable!(),
                    }),
                },
                FallbackMarker::default(),
            );
            assert_eq!(
                resolver
                    .resolve_delegated(&request, &delegation)
                    .unwrap_err(),
                ResolverError::Port53InterceptionDetected
            );
        }

        let bogus = RecoveryDohFallbackDelegatedResolver::new(
            TestDelegatedResolver::error(|| ResolverError::Port53InterceptionDetected),
            TestDelegatedResolver::error(|| ResolverError::DnssecFailed),
            FallbackMarker::default(),
        );
        assert_eq!(
            bogus.resolve_delegated(&request, &delegation).unwrap_err(),
            ResolverError::DnssecFailed
        );
    }

    #[test]
    fn relay_live_query_key_ignores_dns_id_and_restores_each_callers_id() {
        let first = vec![0x12, 0x34, 0x01, 0x10, 0, 1];
        let second = vec![0xab, 0xcd, 0x01, 0x10, 0, 1];
        let (first_key, first_id) = dns_relay_coalescing_key(&first).unwrap();
        let (second_key, second_id) = dns_relay_coalescing_key(&second).unwrap();

        assert_eq!(first_key, second_key);
        assert_eq!(first_id, 0x1234);
        assert_eq!(second_id, 0xabcd);

        let relayed = vec![0x12, 0x34, 0x81, 0x80];
        assert_eq!(
            restore_dns_relay_response_id(relayed, second_id).unwrap(),
            vec![0xab, 0xcd, 0x81, 0x80]
        );
        assert!(matches!(
            dns_relay_coalescing_key(&[0]),
            Err(ResolverError::InvalidDnsResponse)
        ));
    }

    #[test]
    fn coalesced_relay_follower_inherits_peer_and_retry_metadata() {
        let peer: SocketAddr = "203.0.113.80:12038".parse().unwrap();
        let query = vec![0xab, 0xcd, 0x01, 0x10, 0, 1];
        let (key, _) = dns_relay_coalescing_key(&query).unwrap();
        let flight = Arc::new(DnsRelayFlight {
            result: Mutex::new(Some(Ok(DnsRelayFlightSuccess {
                response: vec![0x12, 0x34, 0x81, 0x80],
                metadata: DnsRelayTraceMetadata {
                    peer: Some(peer),
                    retries: 1,
                    service_advertised: Some(true),
                    error: None,
                },
            }))),
            completed: Condvar::new(),
        });
        let live_queries = Arc::new(Mutex::new(HashMap::from([(key, flight)])));
        let attempts = Arc::new(DnsRelayAttemptTracker::default());
        let trace = DnsTraceRecorder::default();
        let transport = HnsP2pDnsTransport {
            client: Arc::new(Mutex::new(None)),
            initialization_error: Some("leader-only client is unused by follower".to_owned()),
            peer_store_path: PathBuf::new(),
            network_kind: NetworkKind::Regtest,
            peer_state: None,
            proof_peer: Arc::new(Mutex::new(None)),
            trace: trace.clone(),
            endpoint_policy: DnsEndpointPolicy::for_network(NetworkKind::Regtest),
            live_queries,
            attempts: Arc::clone(&attempts),
        };

        attempts.begin(0);
        assert_eq!(
            transport.traced_exchange(&query).unwrap(),
            vec![0xab, 0xcd, 0x81, 0x80]
        );

        assert_eq!(attempts.finish(), vec![peer]);
        assert_eq!(
            trace.relay_snapshot(),
            Some(DnsRelayTraceMetadata {
                peer: Some(peer),
                retries: 1,
                service_advertised: Some(true),
                error: None,
            })
        );
        assert_eq!(trace.snapshot()[0].server, peer.to_string());
        assert!(p2p_dns_relay_trace_json(trace.relay_snapshot()).contains(
            r#""attempted":true,"peer":"203.0.113.80:12038","serviceAdvertised":true,"retryCount":1"#,
        ));
    }

