    #[test]
    fn hns_address_presence_without_required_tlsa_is_a_root_failure() {
        let now = now_unix_seconds();
        let host = CanonicalHost::parse("origin.welcome").unwrap();
        let query = OriginQuery::new(
            host.clone(),
            OriginScheme::Https,
            None,
            ProtocolCapabilities::all(),
        );
        let base = temp_dir_path("delegated-hns-tlsa-nxdomain");
        let origin = NamespaceOriginContext {
            key: NamespaceOriginKey {
                profile: base.clone(),
                host: host.as_str().to_owned(),
                scheme: "https".to_owned(),
                port: 443,
                supported_protocols: ProtocolCapabilities::all(),
                network: 0,
                policy_revision: 0,
                binding_revision: 0,
            },
            base,
            network: NetworkKind::Mainnet,
            binding: NamespaceBindingSnapshot::default(),
        };
        let a_request = ResolutionRequest {
            qname: host.as_str().to_owned(),
            qtype: RecordType::A.code(),
        };
        let aaaa_request = ResolutionRequest {
            qname: host.as_str().to_owned(),
            qtype: RecordType::Aaaa.code(),
        };
        let https_request = ResolutionRequest {
            qname: host.as_str().to_owned(),
            qtype: RecordType::Https.code(),
        };
        let tlsa_request = ResolutionRequest {
            qname: "_443._tcp.origin.welcome".to_owned(),
            qtype: RecordType::Tlsa.code(),
        };
        let resolver = RequestMapResolver {
            answers: HashMap::from([
                (
                    a_request,
                    resolution_answer(
                        host.as_str(),
                        vec![address_record(host.as_str(), [192, 0, 2, 50])],
                        true,
                    ),
                ),
                (
                    aaaa_request,
                    resolution_answer(host.as_str(), Vec::new(), true),
                ),
                (
                    https_request,
                    resolution_answer(host.as_str(), Vec::new(), true),
                ),
            ]),
            name_not_found: HashSet::from([tlsa_request]),
            requests: Arc::new(Mutex::new(Vec::new())),
        };

        let delegated_evidence = HnsProofEvidenceRecorder::default();
        delegated_evidence
            .record(
                "welcome",
                HnsProofObservation {
                    anchor: ResourceValueAnchor {
                        tree_root: Hash::new([11; 32]),
                        height: Height(45),
                    },
                    exists: true,
                    has_delegation: true,
                    observed_at_unix: now,
                    expires_at_unix: now.saturating_add(60),
                },
            )
            .unwrap();
        let delegated = match build_present_root_plan(
            &resolver,
            Namespace::Hns,
            &query,
            &origin,
            now,
            &delegated_evidence,
            &IcannEvidenceRecorder::default(),
        ) {
            Ok(_) => panic!("secure HNS address presence without TLSA must fail classification"),
            Err(error) => error,
        };
        assert_eq!(delegated.0.kind(), RootFailureKind::Unsupported);

        let native_evidence = HnsProofEvidenceRecorder::default();
        native_evidence
            .record(
                "welcome",
                HnsProofObservation {
                    anchor: ResourceValueAnchor {
                        tree_root: Hash::new([11; 32]),
                        height: Height(45),
                    },
                    exists: true,
                    has_delegation: false,
                    observed_at_unix: now,
                    expires_at_unix: now.saturating_add(60),
                },
            )
            .unwrap();
        let native = match build_present_root_plan(
            &resolver,
            Namespace::Hns,
            &query,
            &origin,
            now,
            &native_evidence,
            &IcannEvidenceRecorder::default(),
        ) {
            Ok(_) => panic!("native HNS TLSA NXDOMAIN must fail closed"),
            Err(error) => error,
        };
        assert_eq!(native.0.kind(), RootFailureKind::IndeterminateDnssec);
    }

    #[test]
    fn hns_https_h3_h2_raw_alpn_uses_tcp_tlsa_fallback() {
        let now = now_unix_seconds();
        let host = "denuoweb";
        let udp_tlsa_owner = format!("_443._udp.{host}");
        let tcp_tlsa_owner = format!("_443._tcp.{host}");
        let query = OriginQuery::new(
            CanonicalHost::parse(host).unwrap(),
            OriginScheme::Https,
            None,
            ProtocolCapabilities::all(),
        );
        let origin = NamespaceOriginContext {
            key: NamespaceOriginKey {
                profile: temp_dir_path("hns-protocol-tlsa-fallback"),
                host: host.to_owned(),
                scheme: "https".to_owned(),
                port: 443,
                supported_protocols: ProtocolCapabilities::all(),
                network: 0,
                policy_revision: 0,
                binding_revision: 0,
            },
            base: temp_dir_path("hns-protocol-tlsa-fallback-base"),
            network: NetworkKind::Mainnet,
            binding: NamespaceBindingSnapshot::default(),
        };
        let evidence = HnsProofEvidenceRecorder::default();
        evidence
            .record(
                host,
                HnsProofObservation {
                    anchor: ResourceValueAnchor {
                        tree_root: Hash::new([59; 32]),
                        height: Height(1_009),
                    },
                    exists: true,
                    has_delegation: true,
                    observed_at_unix: now,
                    expires_at_unix: now.saturating_add(60),
                },
            )
            .unwrap();
        let requests = Arc::new(Mutex::new(Vec::new()));
        let resolver = RequestMapResolver {
            answers: HashMap::from([
                (
                    ResolutionRequest {
                        qname: host.to_owned(),
                        qtype: RecordType::A.code(),
                    },
                    resolution_answer(host, vec![address_record(host, [35, 212, 156, 128])], true),
                ),
                (
                    ResolutionRequest {
                        qname: host.to_owned(),
                        qtype: RecordType::Aaaa.code(),
                    },
                    resolution_answer(host, Vec::new(), true),
                ),
                (
                    ResolutionRequest {
                        qname: host.to_owned(),
                        qtype: RecordType::Https.code(),
                    },
                    resolution_answer(
                        host,
                        vec![https_alpn_record(
                            host,
                            &[b"h3".as_slice(), b"h2".as_slice()],
                        )],
                        true,
                    ),
                ),
                (
                    ResolutionRequest {
                        qname: udp_tlsa_owner.clone(),
                        qtype: RecordType::Tlsa.code(),
                    },
                    resolution_answer(&udp_tlsa_owner, Vec::new(), true),
                ),
                (
                    ResolutionRequest {
                        qname: tcp_tlsa_owner.clone(),
                        qtype: RecordType::Tlsa.code(),
                    },
                    resolution_answer(
                        &tcp_tlsa_owner,
                        vec![tlsa_record(&tcp_tlsa_owner, 0x36)],
                        true,
                    ),
                ),
            ]),
            name_not_found: HashSet::new(),
            requests: Arc::clone(&requests),
        };

        let build = build_present_root_plan(
            &resolver,
            Namespace::Hns,
            &query,
            &origin,
            now,
            &evidence,
            &IcannEvidenceRecorder::default(),
        )
        .unwrap();
        let RootLookup::Present(plan) = build.lookup else {
            panic!("secure TCP TLSA must select the advertised HTTP/2 candidate");
        };

        assert_eq!(
            plan.service().selected_protocol(),
            ApplicationProtocol::Http2
        );
        assert_eq!(plan.service().transport(), ServiceTransport::Tcp);
        assert_eq!(plan.tls_policy(), TlsTrustPolicy::Dane);
        assert_eq!(plan.tlsa_records().len(), 1);
        let requests = requests.lock().unwrap();
        assert!(requests.iter().any(|request| {
            request.qname == udp_tlsa_owner && request.qtype == RecordType::Tlsa.code()
        }));
        assert!(requests.iter().any(|request| {
            request.qname == tcp_tlsa_owner && request.qtype == RecordType::Tlsa.code()
        }));
    }

